				if (sd > 0.9) col += uSunColor * (pow(sd, 300.0) * 0.45 + pow(sd, 40.0) * 0.16) * (1.0 - sunT) * (1.0 - uNight) * (1.0 - uGloom * 0.6) * smoothstep(-0.02, 0.06, uSunDir.y);
